//! 📸️ Handcrafted JPEG raster, frame, quantization and Huffman entities.
use super::*;
use std::collections::{BTreeMap,BTreeSet};
use semio_framework_os_kernel::{sqlite_snapshot::{artifact::{Cell,Projection,reconstruct_text},validate_sqlite_database_schema,SqliteDatabase,SqliteRow,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase},ArtifactSqliteSnapshot};

fn octet(row:&SqliteRow,column:usize)->Result<u8,String>{u8::try_from(row.integer(column)?).map_err(|error|error.to_string())}
fn short(row:&SqliteRow,column:usize)->Result<u16,String>{u16::try_from(row.integer(column)?).map_err(|error|error.to_string())}
fn unsigned(row:&SqliteRow,column:usize)->Result<u32,String>{u32::try_from(row.integer(column)?).map_err(|error|error.to_string())}
fn checkpoint(control:&mut SqliteSnapshotControl<'_>,position:usize,total:usize)->Result<(),String>{if position%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,position,total)?;}Ok(())}
fn identifiers<'a>(rows:impl IntoIterator<Item=&'a SqliteRow>,control:&mut SqliteSnapshotControl<'_>)->Result<BTreeSet<i64>,String>{let mut keys=BTreeSet::new();for(position,row)in rows.into_iter().enumerate(){checkpoint(control,position,0)?;keys.insert(row.rowid);}Ok(keys)}
fn entities<'a>(database:&'a SqliteDatabase,table:&str,control:&mut SqliteSnapshotControl<'_>)->Result<&'a [SqliteRow],String>{let rows=&database.table(table)?.rows;let mut keys=BTreeSet::new();for(position,row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;if row.rowid<=0||row.integer(0)?!=row.rowid||!keys.insert(row.rowid){return Err(format!("{table} requires unique positive aliased identities"));}}Ok(rows)}
fn groups<'a>(database:&'a SqliteDatabase,table:&str,parents:&BTreeSet<i64>,control:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,Vec<&'a SqliteRow>>,String>{let rows=entities(database,table,control)?;let mut groups=BTreeMap::<i64,Vec<&SqliteRow>>::new();for(position,row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;let owner=row.integer(1)?;if !parents.contains(&owner){return Err(format!("{table} names an unknown owner"));}groups.entry(owner).or_default().push(row);}for rows in groups.values_mut(){let mut ordered=vec![None;rows.len()];for(position,row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;let ordinal=usize::try_from(row.integer(2)?).map_err(|error|error.to_string())?;let slot=ordered.get_mut(ordinal).ok_or("JPEG child ordinals must be dense")?;if slot.replace(*row).is_some(){return Err("JPEG child ordinals must be unique".into());}}let total=ordered.len();rows.clear();for(position,row)in ordered.into_iter().enumerate(){checkpoint(control,position,total)?;rows.push(row.ok_or("JPEG child ordinals must be dense")?);}}Ok(groups)}
fn ordered<'a>(database:&'a SqliteDatabase,table:&str,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<&'a SqliteRow>,String>{Ok(groups(database,table,&BTreeSet::from([1]),control)?.remove(&1).unwrap_or_default())}
fn optional<'a>(database:&'a SqliteDatabase,table:&str,control:&mut SqliteSnapshotControl<'_>)->Result<Option<&'a SqliteRow>,String>{let rows=entities(database,table,control)?;if rows.len()>1||rows.first().is_some_and(|row|row.rowid!=1){return Err(format!("{table} optional identity must be one"));}Ok(rows.first())}
fn grid_size(width:u32,height:u32,channels:usize)->Result<usize,String>{usize::try_from(u64::from(width)*u64::from(height)).map_err(|error|error.to_string())?.checked_mul(channels).ok_or_else(||"JPEG raster byte count overflow".into())}
fn write_rgba(out:&mut Projection<'_,'_>,width:u32,height:u32,pixels:&[u8])->Result<(),String>{if pixels.len()!=grid_size(width,height,4)?{return Err("JPEG raster requires a complete RGBA grid".into());}for(ordinal,pixel)in pixels.chunks_exact(4).enumerate(){let x=(ordinal as u64)%u64::from(width);let y=(ordinal as u64)/u64::from(width);out.insert("jpg_rgba_pixel",&[Cell::Integer(1),Cell::Integer(x as i64),Cell::Integer(y as i64),Cell::Integer(pixel[0].into()),Cell::Integer(pixel[1].into()),Cell::Integer(pixel[2].into()),Cell::Integer(pixel[3].into())])?;}Ok(())}
fn write_rgb(out:&mut Projection<'_,'_>,thumbnail:&JfifThumbnail)->Result<(),String>{if thumbnail.rgb_data.len()!=grid_size(thumbnail.width.into(),thumbnail.height.into(),3)?{return Err("JPEG thumbnail requires a complete RGB grid".into());}for(ordinal,pixel)in thumbnail.rgb_data.chunks_exact(3).enumerate(){out.insert("jpg_thumbnail_rgb_pixel",&[Cell::Integer(1),Cell::Integer((ordinal%usize::from(thumbnail.width)) as i64),Cell::Integer((ordinal/usize::from(thumbnail.width)) as i64),Cell::Integer(pixel[0].into()),Cell::Integer(pixel[1].into()),Cell::Integer(pixel[2].into())])?;}Ok(())}
fn read_grid(database:&SqliteDatabase,table:&str,width:u32,height:u32,channels:usize,present:bool,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<u8>,String>{let rows=entities(database,table,control)?;if !present&&!rows.is_empty(){return Err("JPEG absent thumbnail cannot own pixel rows".into());}let bytes=grid_size(width,height,channels)?;if rows.len()!=bytes/channels{return Err("JPEG pixel rows must fill the declared grid".into());}control.check_value_bytes(bytes)?;let mut pixels=vec![0;bytes];let mut seen=vec![false;rows.len()];for(position,row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;let x=unsigned(row,2)?;let y=unsigned(row,3)?;if row.integer(1)?!=1||x>=width||y>=height{return Err("JPEG pixel lies outside its declared owner or grid".into());}let ordinal=usize::try_from(u64::from(y)*u64::from(width)+u64::from(x)).map_err(|error|error.to_string())?;if std::mem::replace(&mut seen[ordinal],true){return Err("JPEG pixels must have unique coordinates".into());}for channel in 0..channels{pixels[ordinal*channels+channel]=octet(row,4+channel)?;}}Ok(pixels)}
fn read_octets(rows:&[&SqliteRow],control:&mut SqliteSnapshotControl<'_>)->Result<Vec<u8>,String>{let mut bytes=Vec::new();for(position,row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;bytes.push(octet(row,3)?);}Ok(bytes)}

impl ArtifactSqliteSnapshot for JpgSnapshot{
 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn validate_sqlite_snapshot_subset(&self,dialect:&store::io_schema::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{
  control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;if dialect.artifact_kind!="s.stdio.jpg"||dialect.standard!="jfif-1.01"||!matches!(dialect.subset.as_str(),"*"|"baseline"){return Err(format!("JPEG does not own semantic subset {}",dialect.to_coordinate()).into());}if database.table("jpg_document")?.single_row()?.text(1)?!=self.schema{return Err("JPEG document schema identity disagrees with its owned snapshot".to_string().into());}
  let diagnostics=if dialect.subset=="baseline"{crate::standards::v_jfif_1_01::subsets::baseline::schema::check_baseline_conformance_with(self,&mut |position,total|control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,position,total))?}else{Vec::new()};if diagnostics.iter().any(|diagnostic|matches!(diagnostic.severity,dsl::Severity::Error|dsl::Severity::Fatal)){Err(store::io_schema::IoError{message:"JPEG baseline conformance rejected the owned snapshot".into(),diagnostics})}else{Ok(store::io_schema::IoOutcome{value:(),diagnostics})}
 }
 fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{
  let mut out=Projection::new(Self::SQLITE_SCHEMA,control)?;let units=match self.jfif_density_units{JfifDensityUnits::Aspect=>"aspect",JfifDensityUnits::PixelsPerInch=>"pixelsPerInch",JfifDensityUnits::PixelsPerCm=>"pixelsPerCm"};out.insert("jpg_document",&[Cell::Text(&self.schema),Cell::Integer(self.width.into()),Cell::Integer(self.height.into()),self.re_encode_quality.map_or(Cell::Null,|value|Cell::Integer(value.into())),Cell::Integer(self.jfif_version.0.into()),Cell::Integer(self.jfif_version.1.into()),Cell::Text(units),Cell::Integer(self.jfif_x_density.into()),Cell::Integer(self.jfif_y_density.into()),Cell::Integer(self.sof_marker.into()),Cell::Integer(i64::from(self.arithmetic)),self.restart_interval.map_or(Cell::Null,|value|Cell::Integer(value.into()))])?;write_rgba(&mut out,self.width,self.height,&self.pixels)?;
  if let Some(thumbnail)=&self.jfif_thumbnail{out.insert("jpg_thumbnail",&[Cell::Integer(thumbnail.width.into()),Cell::Integer(thumbnail.height.into())])?;write_rgb(&mut out,thumbnail)?;}
  let mut quantizers=BTreeSet::new();for(position,table)in self.quant_tables.iter().enumerate(){if position%256==0{out.checkpoint()?;}quantizers.insert(table.id);}if let Some(frame)=&self.frame{for(position,component)in frame.components.iter().enumerate(){if position%256==0{out.checkpoint()?;}quantizers.insert(component.quant_table_id);}}for quantizer in quantizers{out.insert_key("jpg_quantizer",quantizer.into(),&[Cell::Integer(1)])?;}
  if let Some(frame)=&self.frame{out.insert("jpg_frame",&[Cell::Integer(frame.precision.into()),Cell::Integer(frame.width.into()),Cell::Integer(frame.height.into())])?;for(ordinal,component)in frame.components.iter().enumerate(){out.insert("jpg_frame_component",&[Cell::Integer(1),Cell::Integer(ordinal as i64),Cell::Integer(component.id.into()),Cell::Integer(component.h_sampling.into()),Cell::Integer(component.v_sampling.into()),Cell::Integer(component.quant_table_id.into())])?;}}
  for(ordinal,table)in self.quant_tables.iter().enumerate(){let id=out.insert("jpg_quantization_table",&[Cell::Integer(1),Cell::Integer(ordinal as i64),Cell::Integer(table.id.into()),Cell::Integer(table.precision.into())])?;for(zigzag,value)in table.values.iter().enumerate(){out.insert("jpg_quantization_coefficient",&[Cell::Integer(id),Cell::Integer(zigzag as i64),Cell::Integer((*value).into())])?;}}
  for(ordinal,table)in self.huffman_tables.iter().enumerate(){let class=match table.class{JpgHuffmanClass::Dc=>"dc",JpgHuffmanClass::Ac=>"ac"};let id=out.insert("jpg_huffman_table",&[Cell::Integer(1),Cell::Integer(ordinal as i64),Cell::Integer(table.id.into()),Cell::Text(class)])?;for(length,count)in table.bits.iter().enumerate(){out.insert("jpg_huffman_code_length",&[Cell::Integer(id),Cell::Integer(length as i64),Cell::Integer((*count).into())])?;}for(ordinal,symbol)in table.values.iter().enumerate(){out.insert("jpg_huffman_symbol",&[Cell::Integer(id),Cell::Integer(ordinal as i64),Cell::Integer((*symbol).into())])?;}}
  for(ordinal,segment)in self.other_segments.iter().enumerate(){let id=out.insert("jpg_segment",&[Cell::Integer(1),Cell::Integer(ordinal as i64),Cell::Integer(segment.marker.into())])?;for(ordinal,octet)in segment.data.iter().enumerate(){out.insert("jpg_segment_octet",&[Cell::Integer(id),Cell::Integer(ordinal as i64),Cell::Integer((*octet).into())])?;}}out.finish()
 }
 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{
  validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits()).map_err(|error|error.to_string())?;control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;let document=database.table("jpg_document")?.single_row()?;if document.rowid!=1||document.integer(0)?!=1{return Err("JPEG document identity must be one".into());}let width=unsigned(document,2)?;let height=unsigned(document,3)?;let pixels=read_grid(database,"jpg_rgba_pixel",width,height,4,true,control)?;
  let thumbnail=optional(database,"jpg_thumbnail",control)?;let thumbnail_width=thumbnail.map(|row|octet(row,1)).transpose()?;let thumbnail_height=thumbnail.map(|row|octet(row,2)).transpose()?;let rgb=read_grid(database,"jpg_thumbnail_rgb_pixel",thumbnail_width.unwrap_or(0).into(),thumbnail_height.unwrap_or(0).into(),3,thumbnail.is_some(),control)?;let jfif_thumbnail=thumbnail.map(|_|JfifThumbnail{width:thumbnail_width.unwrap(),height:thumbnail_height.unwrap(),rgb_data:rgb});
  let frame_row=optional(database,"jpg_frame",control)?;let parents=if frame_row.is_some(){BTreeSet::from([1])}else{BTreeSet::new()};let mut component_rows=groups(database,"jpg_frame_component",&parents,control)?.remove(&1).unwrap_or_default();
  let mut quantizers=BTreeSet::new();let rows=&database.table("jpg_quantizer")?.rows;for(position,row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;let id=octet(row,0)?;if row.rowid!=i64::from(id)||row.integer(1)?!=1||!quantizers.insert(id){return Err("JPEG quantizer identity or document reference is invalid".into());}}let mut used_quantizers=BTreeSet::new();let mut components=Vec::new();for(position,row)in component_rows.drain(..).enumerate(){checkpoint(control,position,0)?;let quant_table_id=octet(row,6)?;if !quantizers.contains(&quant_table_id){return Err("JPEG frame component references an unknown quantizer".into());}used_quantizers.insert(quant_table_id);components.push(JpgFrameComponent{id:octet(row,3)?,h_sampling:octet(row,4)?,v_sampling:octet(row,5)?,quant_table_id});}let frame=frame_row.map(|row|Ok::<_,String>(JpgFrameHeader{precision:octet(row,1)?,width:short(row,2)?,height:short(row,3)?,components})).transpose()?;
  let quant_rows=ordered(database,"jpg_quantization_table",control)?;let keys=identifiers(quant_rows.iter().copied(),control)?;let mut coefficients=groups(database,"jpg_quantization_coefficient",&keys,control)?;let mut quant_tables=Vec::new();for(position,row)in quant_rows.iter().enumerate(){checkpoint(control,position,quant_rows.len())?;let id=octet(row,3)?;if !quantizers.contains(&id){return Err("JPEG quantization definition references an unknown quantizer".into());}used_quantizers.insert(id);let rows=coefficients.remove(&row.rowid).unwrap_or_default();if rows.len()!=64{return Err("JPEG quantization definition requires all64zigzag coefficients".into());}let mut values=[0;64];for(index,row)in rows.iter().enumerate(){values[index]=short(row,3)?;}quant_tables.push(JpgQuantTable{id,precision:octet(row,4)?,values});}if quantizers!=used_quantizers{return Err("JPEG quantizer entity is not referenced by any component or definition".into());}
  let huff_rows=ordered(database,"jpg_huffman_table",control)?;let keys=identifiers(huff_rows.iter().copied(),control)?;let mut lengths=groups(database,"jpg_huffman_code_length",&keys,control)?;let mut symbols=groups(database,"jpg_huffman_symbol",&keys,control)?;let mut huffman_tables=Vec::new();for(position,row)in huff_rows.iter().enumerate(){checkpoint(control,position,huff_rows.len())?;let class=match row.text(4)?{"dc"=>JpgHuffmanClass::Dc,"ac"=>JpgHuffmanClass::Ac,_=>return Err("JPEG Huffman table class must be DC or AC".into())};let rows=lengths.remove(&row.rowid).unwrap_or_default();if rows.len()!=16{return Err("JPEG Huffman table requires all16code-length counts".into());}let mut bits=[0;16];for(index,row)in rows.iter().enumerate(){bits[index]=octet(row,3)?;}huffman_tables.push(JpgHuffmanTable{id:octet(row,3)?,class,bits,values:read_octets(&symbols.remove(&row.rowid).unwrap_or_default(),control)?});}
  let segment_rows=ordered(database,"jpg_segment",control)?;let keys=identifiers(segment_rows.iter().copied(),control)?;let mut octets=groups(database,"jpg_segment_octet",&keys,control)?;let mut other_segments=Vec::new();for(position,row)in segment_rows.iter().enumerate(){checkpoint(control,position,segment_rows.len())?;other_segments.push(JpgSegment{marker:octet(row,3)?,data:read_octets(&octets.remove(&row.rowid).unwrap_or_default(),control)?});}
  let jfif_density_units=match document.text(7)?{"aspect"=>JfifDensityUnits::Aspect,"pixelsPerInch"=>JfifDensityUnits::PixelsPerInch,"pixelsPerCm"=>JfifDensityUnits::PixelsPerCm,_=>return Err("JPEG density unit is unknown".into())};let arithmetic=match document.integer(11)?{0=>false,1=>true,_=>return Err("JPEG arithmetic flag must be boolean".into())};let re_encode_quality=if matches!(document.values.get(4),Some(SqliteValue::Null)){None}else{Some(octet(document,4)?)};let restart_interval=if matches!(document.values.get(12),Some(SqliteValue::Null)){None}else{Some(short(document,12)?)};let result=Self{schema:reconstruct_text(control,document.text(1)?)?,width,height,pixels,re_encode_quality,jfif_version:(octet(document,5)?,octet(document,6)?),jfif_density_units,jfif_x_density:short(document,8)?,jfif_y_density:short(document,9)?,jfif_thumbnail,frame,sof_marker:octet(document,10)?,arithmetic,quant_tables,huffman_tables,restart_interval,other_segments};control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,1,1)?;Ok(result)
 }
}
